-- OnionEye — Stylometric profile seed data for the 9 demo actors in seed.sql.
--
-- Populates 384-d pgvector feature_vectors plus (24, 7, 12) temporal histograms
-- so the dashboard-api /graph endpoint can project deterministic 64-d stylokeys
-- via correlation-engine/pkg/stylokey.Project(). The frontend uses these keys
-- for stylometric cluster layout positioning.
--
-- USAGE:  docker compose exec -T postgres psql -U onioneye -d onioneye < db/seed/stylometric_profiles.sql
-- Idempotent: ON CONFLICT (actor_id) DO NOTHING.


